438: /**
439:  * Base worker class. Handles the async work. Derived classes can override the
440:  * following virtual methods (listed in the order in which they're called):
441:  *
442:  * - DoExecute (abstract, worker pool thread): main work
443:  * - HandleOKCallback (main thread): resolve JS promise on success
444:  * - HandleErrorCallback (main thread): reject JS promise on error
445:  * - DoFinally (main thread): do cleanup regardless of success
446:  */
447: struct BaseWorker {
448:   // Note: storing env is discouraged as we'd end up using it in unsafe places.
449:   BaseWorker (napi_env env,
450:               Database* database,
451:               napi_deferred deferred,
452:               const char* resourceName)
453:     : database_(database), errMsg_(NULL), deferred_(deferred) {
454:     // Note: napi_deferred is a strong reference to the JS promise, so there's no need to
455:     // create a reference ourselves. See `v8_deferred = new v8::Persistent<v8::Value>()` in:
456:     // https://github.com/nodejs/node/commit/7efb8f7619100973877c660d0ee527ea3d92de8d
457: 
458:     napi_value asyncResourceName;
459:     NAPI_STATUS_THROWS_VOID(napi_create_string_utf8(env, resourceName,
460:                                                NAPI_AUTO_LENGTH,
461:                                                &asyncResourceName));
462:     NAPI_STATUS_THROWS_VOID(napi_create_async_work(env, NULL,
463:                                               asyncResourceName,
464:                                               BaseWorker::Execute,
465:                                               BaseWorker::Complete,
466:                                               this, &asyncWork_));
467:   }
468: 
469:   virtual ~BaseWorker () {
470:     delete [] errMsg_;
471:   }
472: 
473:   static void Execute (napi_env env, void* data) {
474:     BaseWorker* self = (BaseWorker*)data;
475: 
476:     // Don't pass env to DoExecute() because use of Node-API
477:     // methods should generally be avoided in async work.
478:     self->DoExecute();
479:   }
480: 
481:   bool SetStatus (leveldb::Status status) {
482:     status_ = status;
483:     if (!status.ok()) {
484:       SetErrorMessage(status.ToString().c_str());
485:       return false;
486:     }
487:     return true;
488:   }
489: 
490:   void SetErrorMessage(const char *msg) {
491:     delete [] errMsg_;
492:     size_t size = strlen(msg) + 1;
493:     errMsg_ = new char[size];
494:     memcpy(errMsg_, msg, size);
495:   }
496: 
497:   virtual void DoExecute () = 0;
498: 
499:   static void Complete (napi_env env, napi_status status, void* data) {
500:     BaseWorker* self = (BaseWorker*)data;
501: 
502:     self->DoComplete(env);
503:     self->DoFinally(env);
504:   }
505: 
506:   void DoComplete (napi_env env) {
507:     if (status_.ok()) {
508:       HandleOKCallback(env, deferred_);
509:     } else {
510:       HandleErrorCallback(env, deferred_);
511:     }
512:   }
513: 
514:   virtual void HandleOKCallback (napi_env env, napi_deferred deferred) {
515:     napi_value argv;
516:     napi_get_undefined(env, &argv);
517:     napi_resolve_deferred(env, deferred, argv);
518:   }
519: 
520:   virtual void HandleErrorCallback (napi_env env, napi_deferred deferred) {
521:     napi_value argv;
522: 
523:     if (status_.IsNotFound()) {
524:       napi_get_undefined(env, &argv);
525:       napi_resolve_deferred(env, deferred, argv);
526:       return;
527:     }
528: 
529:     if (status_.IsCorruption()) {
530:       argv = CreateCodeError(env, "LEVEL_CORRUPTION", errMsg_);
531:     } else if (status_.IsIOError()) {
532:       if (strlen(errMsg_) > 15 && strncmp("IO error: lock ", errMsg_, 15) == 0) { // env_posix.cc
533:         argv = CreateCodeError(env, "LEVEL_LOCKED", errMsg_);
534:       } else if (strlen(errMsg_) > 19 && strncmp("IO error: LockFile ", errMsg_, 19) == 0) { // env_win.cc
535:         argv = CreateCodeError(env, "LEVEL_LOCKED", errMsg_);
536:       } else {
537:         argv = CreateCodeError(env, "LEVEL_IO_ERROR", errMsg_);
538:       }
539:     } else {
540:       argv = CreateError(env, errMsg_);
541:     }
542: 
543:     napi_reject_deferred(env, deferred, argv);
544:   }
545: 
546:   virtual void DoFinally (napi_env env) {
547:     napi_delete_async_work(env, asyncWork_);
548:     deferred_ = NULL;
549:     delete this;
550:   }
551: 
552:   void Queue (napi_env env) {
553:     napi_queue_async_work(env, asyncWork_);
554:   }
555: 
556:   Database* database_;
557: 
558: private:
559:   napi_deferred deferred_;
560:   napi_async_work asyncWork_;
561:   leveldb::Status status_;
562:   char *errMsg_;
563: };
