724: 
725: leveldb::Status threadsafe_open(const leveldb::Options &options,
726:                                 bool multithreading,
727:                                 Database &db_instance) {
728:   // Bypass lock and handles if multithreading is disabled
729:   if (!multithreading) {
730:     return leveldb::DB::Open(options, db_instance.location_, &db_instance.db_);
731:   }
732: 
733:   std::unique_lock<std::mutex> lock(handles_mutex);
734: 
735:   auto it = db_handles.find(db_instance.location_);
736:   if (it == db_handles.end()) {
737:     // Database not opened yet for this location, unless it was with
738:     // multithreading disabled, in which case we're expected to fail here.
739:     LevelDbHandle handle = {nullptr, 0};
740:     leveldb::Status status = leveldb::DB::Open(options, db_instance.location_, &handle.db);
741: 
742:     if (status.ok()) {
743:       handle.open_handle_count++;
744:       db_instance.db_ = handle.db;
745:       db_handles[db_instance.location_] = handle;
746:     }
747: 
748:     return status;
749:   }
750: 
751:   ++(it->second.open_handle_count);
752:   db_instance.db_ = it->second.db;
753: 
754:   return leveldb::Status::OK();
755: }
756: 
757: leveldb::Status threadsafe_close(Database &db_instance) {
758:   std::unique_lock<std::mutex> lock(handles_mutex);
759: 
760:   auto it = db_handles.find(db_instance.location_);
761:   if (it == db_handles.end()) {
762:     // Was not opened with multithreading enabled
763:     delete db_instance.db_;
764:   } else if (--(it->second.open_handle_count) == 0) {
765:     delete it->second.db;
766:     db_handles.erase(it);
767:   }
768: 
769:   // ensure db_ pointer is nullified in Database instance
770:   db_instance.db_ = NULL;
771:   return leveldb::Status::OK();
772: }
